package ara.daily;
import org.json.*;import java.io.*;import java.util.regex.*;
final class NotionDiary {
 static final String BEGIN="ARA-DAY-DATA-BEGIN-V1",END="ARA-DAY-DATA-END-V1";
 static boolean active(JSONObject input)throws Exception{JSONObject d=input.optJSONObject("diary");if(d==null)throw new IOException("하루 기록 본문 데이터가 없습니다.");String date=NotionDaily.date(input);if(!date.equals(d.optString("wake_date"))||!d.optString("wake_at").startsWith(date+"T"))throw new IOException("일기 날짜와 기상일이 다릅니다.");JSONArray records=d.optJSONArray("actual");if(records==null)throw new IOException("행동 기록 형식을 확인해 주세요.");boolean active=false;for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);int count=r.optInt("slot_count",0);if(count<1||count>288)throw new IOException("행동 기록 길이를 확인해 주세요.");if(!r.optString("category_id").equals("기상")&&!r.optString("template_id").equals("wake"))active=true;}return active;}
 static JSONObject save(JSONObject input,JSONObject target,boolean pending,NotionDaily.Call call,NotionDaily.Mark mark)throws Exception{if(!active(input))return new JSONObject().put("skipped",true).put("reason","no_activity").put("date",input.getString("date"));return NotionDaily.save(input,target,pending,call,mark);}
 static String content(JSONObject input)throws Exception{if(!input.has("diary"))return null;active(input);return BEGIN+"\n```json\n"+input.getJSONObject("diary").toString(2)+"\n```\n"+END;}
 static JSONObject newPage(JSONObject props,JSONObject input)throws Exception{return new JSONObject().put("properties",props); }
 static String body(JSONObject fetched)throws Exception{if(!fetched.has("text"))throw new IOException("노션 본문을 확인하지 못했습니다.");String text=fetched.getString("text");int start=text.indexOf("<content>"),end=text.lastIndexOf("</content>");return start>=0&&end>start?text.substring(start+9,end):text;}
 static JSONObject patch(String pageId,String body,String replacement)throws Exception{Pattern begin=Pattern.compile("(?m)^"+BEGIN+"[ \\t]*$"),end=Pattern.compile("(?m)^"+END+"[ \\t]*$");Matcher a=begin.matcher(body),b=end.matcher(body);int n=0,m=0,first=0,last=0;while(a.find()){n++;first=a.start();}while(b.find()){m++;last=b.end();}JSONObject request=new JSONObject().put("page_id",pageId).put("allow_async",false);if(n==0&&m==0){if(body.contains(BEGIN)||body.contains(END))throw new IOException("ARA 기록 구역 표시를 확인해 주세요. 본문은 보존했습니다.");return request.put("command","insert_content").put("position",new JSONObject().put("type","end")).put("content",replacement);}if(n!=1||m!=1||last<first)throw new IOException("ARA 기록 구역의 시작·끝 표시가 변경됐습니다. 다른 본문은 수정하지 않았습니다.");String old=body.substring(first,last);if(old.equals(replacement))return null;return request.put("command","update_content").put("content_updates",new JSONArray().put(new JSONObject().put("old_str",old).put("new_str",replacement)));}
 static final String CHILD_PENDING="ARA-AI-CHILD-PENDING-V1";
 static void writePatch(JSONObject request,NotionDaily.Call call)throws Exception{if(request==null)return;JSONObject result=NotionDaily.decode(call.run("update-page",request));if("async_task".equals(result.optString("type"))||result.has("async_task"))throw new IOException("노션 본문 처리 중입니다. 다음 동기화에서 다시 확인합니다.");}
 static String childId(String body,String title)throws Exception{Matcher m=Pattern.compile("<page\\b[^>]*url=\"([^\"]+)\"[^>]*>([^<]*)</page>").matcher(body);String id="";while(m.find())if(m.group(2).trim().equals(title)){if(!id.isEmpty())throw new IOException("AI 참고 기록 하위 페이지가 여러 개 있습니다.");id=NotionDaily.id(m.group(1).replace("{","").replace("}",""));}return id;}
 static void update(String pageId,JSONObject input,NotionDaily.Call call)throws Exception{String content=content(input);if(content==null)return;String parentBody=body(NotionDaily.decode(call.run("fetch",new JSONObject().put("id",pageId)))),title="ARA AI 기록 · "+NotionDaily.date(input),childId=childId(parentBody,title);if(childId.isEmpty()){if(parentBody.contains(CHILD_PENDING))throw new IOException("AI 하위 페이지 생성 결과를 확인 중입니다. 다음 동기화에서 다시 확인합니다.");writePatch(new JSONObject().put("page_id",pageId).put("command","insert_content").put("position",new JSONObject().put("type","end")).put("content",CHILD_PENDING).put("allow_async",false),call);JSONObject created=NotionDaily.decode(call.run("create-pages",new JSONObject().put("parent",new JSONObject().put("page_id",pageId)).put("allow_async",false).put("pages",new JSONArray().put(new JSONObject().put("properties",new JSONObject().put("title",title)).put("content",content)))));JSONArray pages=created.optJSONArray("pages");if(pages==null||pages.length()==0)pages=created.optJSONArray("results");JSONObject child=pages!=null&&pages.length()>0?pages.getJSONObject(0):created;childId=NotionDaily.id(child.optString("url").isEmpty()?child.optString("id"):child.optString("url"));}else{String childBody=body(NotionDaily.decode(call.run("fetch",new JSONObject().put("id",childId))));if(!childBody.contains(BEGIN)||!childBody.contains(END))throw new IOException("AI 하위 페이지의 ARA 기록 구역을 확인해 주세요.");writePatch(patch(childId,childBody,content),call);}parentBody=body(NotionDaily.decode(call.run("fetch",new JSONObject().put("id",pageId))));if(parentBody.contains(BEGIN)||parentBody.contains(END))writePatch(patch(pageId,parentBody,""),call);if(parentBody.contains(CHILD_PENDING))writePatch(new JSONObject().put("page_id",pageId).put("command","update_content").put("content_updates",new JSONArray().put(new JSONObject().put("old_str",CHILD_PENDING).put("new_str",""))).put("allow_async",false),call);}

}
